mapper.select:
SELECT
fscr.card_id,fscr.card_code,fscr.`name`,faca.`name` categoryName ,fscr.year_period,fscr.start_date,fscr.clean_period,
fscr.depreciation_method,fscr.term,original_value,fscr.residual_rate,fscr.residual_rate_pre,fscr.impairment_prepare,
fscr.already_depreciation_date,fscr.start_depreciation,fscr.month_depreciation,fscr.start_net_value,fscr.create_time,fscr.`status`
from book_fixed_asset_card fscr
LEFT JOIN book_fixed_asset_category faca ON fscr.category_id = faca.category_id
WHERE fscr.del_flag = 0

    and fscr.book_id = #{bookId}


    and fscr.card_code = #{cardCode}


    and fscr.name like concat('%',#{name},'%')


    and fscr.category_id = #{categoryId}


    and fscr.depreciation_method = #{depreciationMethod}
